namespace {using U=std::uint32_t;void put(dfre::AiActorImage& a,U at,U value){std::memcpy(a.data()+at,&value,4);}std::string hex(const dfre::AiActorImage& a){const char* d="0123456789abcdef";std::string s;for(auto n:a){s+=d[n>>4];s+=d[n&15];}return s;}}
int main(){using namespace dfre;U fc,limit,seed,callback,mutation;while(std::cin>>fc>>limit>>seed>>callback>>mutation){MissionTickState state;std::vector<AiItemDefinition> defs(2);defs[1].field_9c=limit;init_mission_tick(state,{},AiActorTables{},AiItemDefinitionTable(defs),{},0);prepare_mission_extra_actor_pool(state);AiActorImage image;image.fill(std::uint8_t(seed));put(image,0,1);put(image,4,1);put(image,0xc,0);put(image,0x18,0);put(image,0xfc,fc);put(image,0x10c,callback);apply_mission_actor_image(state,{4,0},image);state.extra_actor_encoding[0].raw_definition=0x1210000;unsigned clears=0,actions=0;AiTickHooks h;h.on_clear=[&](auto ref){++clears;clear_mission_extra_actor(state,ref.index);};h.on_action=[&](auto action){if(action.actor.group!=4)throw MissionTickError("Unexpected fixture callback");++actions;if(mutation){state.tables.extra[0].field_fc^=0xabcdef01;state.tables.extra[0].field_110^=0x42000000;state.stored_extra_actor_images[0][0xe3]^=0x19;}};tick_ai(state.tables,state.ai,state.definitions,[](U){return AiActorBounds{};},0,h);std::cout<<clears<<' '<<actions<<' '<<hex(snapshot_mission_actor(state,{4,0}))<<'\n';}}
